import numpy as np, pandas as pd
train = pd.read_csv('train.csv')
X = train.drop(columns=['target']).to_numpy(float)
y = train['target'].to_numpy(int)

idx = np.arange(len(X))
folds = idx % 5

def acc(pred, yt):
    return float((pred == yt).mean())

def eval_model(name, fit_predict):
    scores=[]
    for f in range(5):
        tr = folds != f
        va = ~tr
        pred = fit_predict(X[tr], y[tr], X[va])
        scores.append(acc(pred, y[va]))
    print(name, 'mean', np.mean(scores), 'folds', [round(s,4) for s in scores])

def majority(Xtr,ytr,Xva):
    cls = np.bincount(ytr).argmax()
    return np.full(len(Xva), cls)

def centroid(Xtr,ytr,Xva):
    m0 = Xtr[ytr==0].mean(axis=0)
    m1 = Xtr[ytr==1].mean(axis=0)
    s0 = ((Xva-m0)**2).sum(axis=1)
    s1 = ((Xva-m1)**2).sum(axis=1)
    return (s1 < s0).astype(int)

def ridge(Xtr,ytr,Xva, lam=1.0):
    Xtr1 = np.c_[np.ones(len(Xtr)), Xtr]
    Xva1 = np.c_[np.ones(len(Xva)), Xva]
    I = np.eye(Xtr1.shape[1]); I[0,0]=0
    beta = np.linalg.solve(Xtr1.T@Xtr1 + lam*I, Xtr1.T@ytr)
    return (Xva1@beta >= 0.5).astype(int)

def diag_nb(Xtr,ytr,Xva):
    out=[]
    priors = [np.mean(ytr==c) for c in [0,1]]
    means = [Xtr[ytr==c].mean(axis=0) for c in [0,1]]
    vars_ = [Xtr[ytr==c].var(axis=0)+1e-6 for c in [0,1]]
    scores=[]
    for c in [0,1]:
        ll = -0.5*np.sum(np.log(2*np.pi*vars_[c]) + (Xva-means[c])**2/vars_[c], axis=1) + np.log(priors[c])
        scores.append(ll)
    return (scores[1] > scores[0]).astype(int)

def lda(Xtr,ytr,Xva, lam=1e-3):
    X0 = Xtr[ytr==0]; X1 = Xtr[ytr==1]
    m0 = X0.mean(axis=0); m1 = X1.mean(axis=0)
    S0 = np.cov(X0, rowvar=False)
    S1 = np.cov(X1, rowvar=False)
    S = ((len(X0)-1)*S0 + (len(X1)-1)*S1) / (len(Xtr)-2)
    S = S + lam*np.eye(S.shape[0])
    invS = np.linalg.inv(S)
    def score(X, m, prior):
        return X@invS@m - 0.5*m@invS@m + np.log(prior)
    s0 = score(Xva,m0,len(X0)/len(Xtr))
    s1 = score(Xva,m1,len(X1)/len(Xtr))
    return (s1>s0).astype(int)

for name, fn in [('majority', majority), ('centroid', centroid), ('ridge', ridge), ('diag_nb', diag_nb), ('lda', lda)]:
    eval_model(name, fn)
